import CoreGraphics
import CoreImage
import CoreText
import Testing
@testable import StridDocuments

/// Draws a white 1400x900 page with a few lines of body text and, optionally, a QR code at
/// `qrRect`. The code is generated by Core Image so the test needs no fixture file.
private func page(qr qrRect: CGRect?) -> CGImage {
    let w = 1400, h = 900
    let ctx = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: 0,
                        space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue)!
    ctx.setFillColor(gray: 1, alpha: 1)
    ctx.fill(CGRect(x: 0, y: 0, width: w, height: h))
    // Body text: dense enough to look like a statement.
    ctx.setFillColor(gray: 0, alpha: 1)
    let font = CTFontCreateWithName("Helvetica" as CFString, 22, nil)
    for i in 0..<18 {
        let line = CFAttributedStringCreate(nil, "Account No 50100234567890 IFSC HDFC0001234 UPI-RAHUL SHARMA-rahul@okaxis 1,23,456.00 ref \(i)" as CFString,
                                            [kCTFontAttributeName: font] as CFDictionary)!
        ctx.textPosition = CGPoint(x: 40, y: CGFloat(h - 60 - i * 34))
        CTLineDraw(CTLineCreateWithAttributedString(line), ctx)
    }
    if let r = qrRect {
        let filter = CIFilter(name: "CIQRCodeGenerator")!
        filter.setValue(Data(repeating: 0x41, count: 600), forKey: "inputMessage")  // a large (version ~20) code
        filter.setValue("L", forKey: "inputCorrectionLevel")
        let ci = filter.outputImage!
        let cg = CIContext().createCGImage(ci, from: ci.extent)!
        ctx.interpolationQuality = .none
        ctx.draw(cg, in: CGRect(x: r.minX, y: CGFloat(h) - r.maxY, width: r.width, height: r.height))
    }
    return ctx.makeImage()!
}

@Suite("QR / barcode regions") struct BarcodeTests {
    @Test func largeQRIsFoundByTexture() {
        let qr = CGRect(x: 950, y: 300, width: 360, height: 360)
        let rects = Barcodes.denseRegions(in: page(qr: qr))
        #expect(rects.count == 1)
        if let r = rects.first {
            // The region must cover the code (padding may make it a little larger).
            #expect(r.minX <= qr.minX + 8 && r.minY <= qr.minY + 8 && r.maxX >= qr.maxX - 8 && r.maxY >= qr.maxY - 8)
            #expect(r.width < qr.width * 1.4 && r.height < qr.height * 1.4)
        }
    }
    @Test func bodyTextIsNotACode() {
        #expect(Barcodes.denseRegions(in: page(qr: nil)).isEmpty)
    }
    @Test func detectUnionsVisionAndTexture() {
        let rects = Barcodes.detect(in: page(qr: CGRect(x: 950, y: 300, width: 360, height: 360)))
        #expect(rects.count == 1)
    }
}
